// src/server/session-persistence/agirContext.ts
function resolverContextoAgir(sessionId, chatId) {
  if (!sessionId || sessionId.length > 200 || !chatId || chatId.length > 200) {
    return { ok: false, message: "Contexto da sess\xE3o ou conversa inv\xE1lido." };
  }
  const record = getSessionRecord(sessionId);
  if (!record) {
    return { ok: false, message: "A sess\xE3o n\xE3o est\xE1 registrada no servidor. Recarregue a sess\xE3o e tente novamente." };
  }
  let session;
  try {
    session = JSON.parse(record.sessionJson);
  } catch {
    return { ok: false, message: "O contexto persistido da sess\xE3o est\xE1 inv\xE1lido; nenhuma a\xE7\xE3o foi iniciada." };
  }
  if (session.id !== sessionId || session.workspacePath !== record.workspacePath || (session.worktreePath ?? null) !== record.worktreePath) {
    return { ok: false, message: "O contexto persistido da sess\xE3o n\xE3o corresponde ao registro do servidor." };
  }
  if (!Array.isArray(session.chats) || !session.chats.some((chat) => chat.id === chatId)) {
    return { ok: false, message: "A conversa n\xE3o pertence \xE0 sess\xE3o persistida." };
  }
  const activePath = session.worktreePath || session.workspacePath;
  const checked = validateWorkspacePath(activePath);
  if (!checked.valid || !checked.exists || !checked.isDir) {
    return { ok: false, message: "A pasta de trabalho da sess\xE3o n\xE3o est\xE1 acess\xEDvel. Escolha a pasta de novo." };
  }
  return {
    ok: true,
    raiz: checked.realpath,
    permissoes: listSessionToolGrants(sessionId, checked.realpath)
  };
}

