function payloadsDeBloco(bloco) {
  const linhas = bloco.split(/\r?\n/);
  const dados = linhas.filter((linha) => linha.startsWith("data:"));
  if (dados.length === 0) return [];
  const payload = dados.map((linha) => linha.slice(5).replace(/^ /, "")).join("\n").trim();
  return payload ? [payload] : [];
}
function framerSSE() {
  let buffer = "";
  return {
    entrar(texto) {
      buffer += texto;
      const pedacos = buffer.split(/\r?\n\r?\n/);
      buffer = pedacos.pop() ?? "";
      return pedacos.flatMap((bloco) => payloadsDeBloco(bloco));
    },
    fechar() {
      const resto = buffer;
      buffer = "";
      if (!resto.trim()) return [];
      const payloads = payloadsDeBloco(resto);
      if (payloads.length > 0) return payloads;
      return [resto.trim()];
    }
  };
}
function framerNDJSON() {
  let buffer = "";
  return {
    entrar(texto) {
      buffer += texto;
      const linhas = buffer.split("\n");
      buffer = linhas.pop() ?? "";
      return linhas.map((linha) => linha.replace(/\r$/, "")).filter((linha) => linha.trim().length > 0);
    },
    fechar() {
      const resto = buffer;
      buffer = "";
      return resto.trim() ? [resto.trim()] : [];
    }
  };
}
function criarFramer(protocolo) {
  return protocolo === "ollama" ? framerNDJSON() : framerSSE();
}

